"use client";
/* Pebble, from the Piixpal shadcn registry. Options: https://piixpal.dvkk.dev/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Pebble(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("pebble"); }, []);
  return React.createElement("piix-pal", { "pal": "pebble", ...piixAttrs(props) });
}

export default Pebble;
